// 🦉 OWL Wallet Integration Enhancements
async function hasNFT(address) {
  try {
    const response = await fetch(`https://open-api.unisat.io/v1/indexer/address/${address}/brc20/inscriptions`, {
      headers: {
        "accept": "application/json",
        "Authorization": "Bearer 471f29db8512c332250caccc3cd60f9865a33c74e2c90f7d64b99c7ac615216f"
      }
    });

    if (!response.ok) {
      console.error("API error:", response.statusText);
      return false;
    }

    const data = await response.json();
    const hasOwlNFT = data.inscriptions.some(nft => nft.tick === "owl" || nft.tick?.toLowerCase() === "owl");
    return hasOwlNFT;
  } catch (error) {
    console.error("Error checking NFT ownership:", error);
    return false;
  }
}

window.checkNFTAccessAndProceed = async function(address) {
  const granted = await hasNFT(address);
  if (granted) {
    console.log("✅ Access granted: User owns OWL NFT");
    document.body.innerHTML += '<div style="position:fixed;top:20px;left:20px;background:#0f0;padding:10px;border-radius:8px;">Access Granted ✅</div>';
    // TODO: Reveal full site content here
  } else {
    console.log("⛔ Access denied: No OWL NFT found");
    document.body.innerHTML += '<div style="position:fixed;top:20px;left:20px;background:#f00;padding:10px;border-radius:8px;">Access Denied ❌</div>';
    // TODO: Optionally restrict access or redirect
  }
}

// Ось тут виводимо об'єкт глобально (UMD-експорт)
window.satsConnect = {
  WalletSelectModal,
  WalletManager,
  getAddress,
  getNetwork,
  sendBtcTransaction,
  signMessage,
  checkNFTAccessAndProceed
};

